"use client";

import Link from "next/link";

export type StartSuggestion = { id: string; label: string; meta?: string; href: string };
export type StartConfiguration = { greeting: string; suggestions: StartSuggestion[]; examples?: string[] };

/** Suggestions are supplied from saved records, never generated by a model. */
export function StartSuggestions({ suggestions, examples = [], onExample, objectHref = href => href }: Omit<StartConfiguration, "greeting"> & { onExample: (text: string) => void; objectHref?: (href: string) => string }) {
  return <div className="space-y-6 px-1 pt-5">
    {suggestions.length ? <ul aria-label="接下来" className="divide-y divide-line">
      {suggestions.slice(0, 3).map(item => <li key={item.id}>
        <Link href={objectHref(item.href)} className="flex min-h-11 items-center justify-between gap-3 py-2 text-[15px] text-text hover:text-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-focus-ring">
          <span>{item.label}{item.meta ? <span className="ml-2 text-[13px] text-text-2">{item.meta}</span> : null}</span><span aria-hidden="true">→</span>
        </Link>
      </li>)}
    </ul> : examples.length ? <ul aria-label="可以这样问" className="flex flex-wrap gap-2">
      {examples.map(example => <li key={example}><button type="button" onClick={() => onExample(example)} className="min-h-11 rounded-full border border-line px-3 text-[13px] text-text-2 hover:bg-surface-2 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-focus-ring">{example}</button></li>)}
    </ul> : null}
    <nav aria-label="学习工具" className="flex flex-wrap gap-x-4 text-[13px] text-text-2">
      {([["考前冲刺", "/opening/sprint"], ["卡组", "/opening/cards"], ["搜索", "/opening/search"], ["新建课程", "/opening/courses/new"]] as const).map(([label, href]) => <Link key={href} href={objectHref(href)} className="inline-flex min-h-11 items-center hover:text-text focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-focus-ring">{label}</Link>)}
    </nav>
  </div>;
}
